package com.medicine.management.controller;
import com.medicine.management.common.ApiResponse; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpSession; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.core.AuthenticationException; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthenticationManager manager; public AuthController(AuthenticationManager manager){this.manager=manager;} public record LoginRequest(String username,String password){} @PostMapping("/login") public ApiResponse<Map<String,String>> login(@RequestBody LoginRequest request, HttpServletRequest http){ try { Authentication a=manager.authenticate(new UsernamePasswordAuthenticationToken(request.username(),request.password())); var context=SecurityContextHolder.createEmptyContext(); context.setAuthentication(a); SecurityContextHolder.setContext(context); HttpSession session=http.getSession(true); session.setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,context); return ApiResponse.ok(profile(a)); } catch(AuthenticationException e){ return new ApiResponse<>(false,"账号或密码错误",null); } } @PostMapping("/logout") public ApiResponse<Void> logout(HttpServletRequest request){ HttpSession session=request.getSession(false); if(session!=null) session.invalidate(); return ApiResponse.ok(null); } @GetMapping("/me") public ApiResponse<Map<String,String>> me(Authentication a){return ApiResponse.ok(profile(a));} private Map<String,String> profile(Authentication a){String role=a.getAuthorities().stream().findFirst().map(x->x.getAuthority().replace("ROLE_","")).orElse("OPERATOR"); return Map.of("username",a.getName(),"role",role);} }
